UPDATE manual_sections
SET body = body || '\n\nExempt နှင့် Restrict ကို အောက်ပါအတိုင်း ခွဲသုံးပါ။ Exempt 1h = inquiry rate limit ကို 1 hour bypass ပေးတာဖြစ်ပြီး trusted/test account က free-text FAQ/AI/handoff flow ကို ပုံမှန်ဆက်သုံးနိုင်ပါတယ်။ Restrict 2h = free-text inquiries ကို 2 hours ပိတ်တာဖြစ်ပြီး AI call နှင့် escalation အသစ် မလုပ်ပါ။ Restrict ပေးလျှင် active Exempt ကို ဖယ်ပေးပါတယ်။ Unlock Now = cooldown/temporary restriction ကို ချက်ချင်းဖယ်တာသာဖြစ်ပြီး Exempt မပေးပါ။ Permanent Ban = Owner-only indefinite free-text block ဖြစ်ပါတယ်။\n\nSafe commands ကိုခွင့်ပြုထားသော်လည်း command/button spam ကို Interaction Flood Guard သီးသန့်ကာကွယ်ပါတယ်။ Normal users အတွက် private chat command + inline callback + message စုစုပေါင်း 20 interactions / 60 seconds ဖြစ်ပြီး ကျော်လျှင် 5-minute UI flood block ဝင်ပါတယ်။ Active cooldown/restriction/permanent-ban users အတွက် tighter 6 interactions / 60 seconds သုံးပါတယ်။ ပထမ blocked interaction မှာသာ warning ပြပြီး နောက် blocked traffic ကို silent drop လုပ်ကာ warning ကို 5 minutes တစ်ကြိမ်ထက်မပိုအောင် throttle လုပ်ပါတယ်။ Owner/Sudo ကို flood guard မပိတ်ပါ။ Exempt 1h သည် inquiry rate limit ကိုသာ bypass လုပ်ပြီး flood guard ကို bypass မလုပ်ပါ။',
    version = version + 1,
    updated_at = CURRENT_TIMESTAMP
WHERE section_key='spam-protection' AND manual_key IN ('owner','admin');
